/**
 * UI kit library — AUTO-GENERATED by scripts/sync-template.ts from the WorldForge taxonomy
 * (packages/core/src/taxonomy/ui-kits.ts). Every kit is a complete design system; `src/ui/kit.ts`
 * renders the one `GameConfig.ui.kit` selects. Editing a kit here is fine (it is your project), but a
 * WorldForge regeneration rewrites this file — tune `kit.ts` or the GameSpec instead to keep changes.
 */

/** Decoration drawn on every panel of the kit (UI parts only, no image assets). */
export type UiOrnament = "none" | "rivets" | "scanlines" | "brackets" | "filigree" | "stripes" | "glow" | "grain" | "notch" | "stitch" | "chevrons" | "bubbles" | "grid";
/** Button feedback of the kit. */
export type UiPress = "squash" | "slide" | "flicker" | "pulse" | "none";
/** How a screen (kit.Window) appears. */
export type UiEnter = "pop" | "slide" | "fade" | "none";
/** Click feedback of the kit (built-in Roblox sounds). */
export type UiSound = "soft" | "click" | "beep" | "pop" | "thud" | "none";
/** Hover / selection feedback. */
export type UiHover = "lift" | "glow" | "tint" | "outline" | "none";
/** Click effect left at the cursor. */
export type UiClickFx = "ripple" | "burst" | "flash" | "none";
/** Rarity treatment of item tiles. */
export type UiRarityFx = "glow" | "sparkle" | "shine" | "none";
/** Celebration of a win (purchase, quest, level). */
export type UiCelebrate = "confetti" | "coins" | "sparks" | "rays" | "none";
/** Bars: one smooth fill or notched segments. */
export type UiBarStyle = "smooth" | "segmented";

export interface UiKitTokens {
	paper: string;
	paperDark: string;
	ink: string;
	inkSoft: string;
	text: string;
	textDark: string;
	primary: [string, string];
	gold: [string, string];
	danger: [string, string];
	info: [string, string];
	pill: string;
	pillStroke: string;
	tile: string;
	tileStroke: string;
}

export interface UiKitShape {
	radius: number;
	strokeThickness: number;
	gradients: boolean;
	shadow: number;
	shadowTransparency: number;
	bevel: boolean;
	textOutline: number;
	panelTransparency: number;
	font: Enum.Font;
	fontBody: Enum.Font;
	ornament: UiOrnament;
	press: UiPress;
	enter: UiEnter;
	/** multiplies every text size (decorative fonts need more room) */
	textScale: number;
	sound: UiSound;
	hover: UiHover;
	clickFx: UiClickFx;
	rarityFx: UiRarityFx;
	/** animation intensity 0…1.4 (0 disables the looping effects) */
	motion: number;
	celebrate: UiCelebrate;
	barStyle: UiBarStyle;
}

export interface UiKit {
	id: string;
	name: string;
	description: string;
	tokens: UiKitTokens;
	shape: UiKitShape;
}

